{
  "goal": "Analyze quarterly sales CSV files for data quality, repair recoverable issues, revalidate, compute quarterly statistics, merge results, run a quality review, and generate a consolidated Markdown report with evidence log.",
  "steps": [
    {
      "kind": "foreach",
      "name": "processFiles",
      "over": "inputs",
      "description": "For each quarterly sales CSV: inspect schema, detect quality issues, repair, revalidate, compute stats, and combine results.",
      "output": {
        "name": "fileResults",
        "typeName": "List<Record>",
        "fields": [
          {"name": "schema", "typeName": "Record"},
          {"name": "detectedIssues", "typeName": "Record"},
          {"name": "repairSummary", "typeName": "Record"},
          {"name": "validationResult", "typeName": "Record"},
          {"name": "quarterStats", "typeName": "Record"}
        ]
      },
      "body": [
        {
          "kind": "primitive",
          "name": "inspectSchema",
          "capability": "csv.inspect_schema",
          "code": {"path": "${item}"},
          "description": "Inspect CSV schema, columns, row count, and known issues.",
          "output": {
            "name": "schema",
            "typeName": "Record",
            "fields": [
              {"name": "columns", "typeName": "List<Record>"},
              {"name": "row_count", "typeName": "Integer"},
              {"name": "issues", "typeName": "List<String>"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "detectIssues",
          "capability": "execute_python",
          "description": "Detect type errors, missing values, duplicates, and outliers.",
          "code": "import pandas as pd\ndf = pd.read_csv(\"${item}\")\nissues = {\"type_errors\": [], \"missing\": {}, \"duplicates\": 0, \"outliers\": {}}\nfor col in df.columns:\n    if df[col].dtype == object:\n        try:\n            pd.to_numeric(df[col])\n        except:\n            issues[\"type_errors\"].append(col)\nissues[\"missing\"] = {c: int(v) for c, v in df.isnull().sum().items() if v > 0}\nissues[\"duplicates\"] = int(df.duplicated().sum())\nfor col in df.select_dtypes(include=\"number\").columns:\n    q1, q3 = df.col.quantile([0.25, 0.75])\n    iqr = q3 - q1\n    n = int(((df[col] < q1 - 1.5*iqr) | (df[col] > q3 + 1.5*iqr)).sum())\n    if n:\n        issues[\"outliers\"][col] = n\nenv[\"detected_issues\"] = issues",
          "output": {
            "name": "detectedIssues",
            "typeName": "Record",
            "fields": [
              {"name": "type_errors", "typeName": "List<String>"},
              {"name": "missing", "typeName": "Record"},
              {"name": "duplicates", "typeName": "Integer"},
              {"name": "outliers", "typeName": "Record"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "repairIssues",
          "capability": "execute_python",
          "description": "Drop duplicates, impute missing values, coerce types, and serialize repaired data.",
          "code": "import pandas as pd\ndf = pd.read_csv(\"${item}\")\nlog = {\"actions\": [], \"rows_dropped\": 0, \"values_imputed\": 0}\ndupes = int(df.duplicated().sum())\nif dupes:\n    df = df.drop_duplicates()\n    log[\"rows_dropped\"] = dupes\n    log[\"actions\"].append(f\"Dropped {dupes} duplicate rows\")\nfor col in df.columns:\n    n_miss = int(df[col].isnull().sum())\n    if n_miss:\n        if pd.api.types.is_numeric_dtype(df[col]):\n            df[col].fillna(df[col].mean(), inplace=True)\n        else:\n            df[col].fillna(\"UNKNOWN\", inplace=True)\n        log[\"values_imputed\"] += n_miss\n        log[\"actions\"].append(f\"Imputed {n_miss} missing values in '{col}'\")\nlog[\"repaired_data\"] = df.to_json()\nenv[\"repair_summary\"] = log",
          "output": {
            "name": "repairSummary",
            "typeName": "Record",
            "fields": [
              {"name": "actions", "typeName": "List<String>"},
              {"name": "rows_dropped", "typeName": "Integer"},
              {"name": "values_imputed", "typeName": "Integer"},
              {"name": "repaired_data", "typeName": "String"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "revalidate",
          "capability": "execute_python",
          "description": "Reparse repaired data and verify all detectable issues are resolved.",
          "code": "import pandas as pd\nrepair = ${repairSummary}\ndf = pd.read_json(repair[\"repaired_data\"])\nresult = {\"schema_ok\": True, \"remaining_issues\": [], \"row_count\": len(df)}\nrem_missing = {c: int(v) for c, v in df.isnull().sum().items() if v > 0}\nfor c, v in rem_missing.items():\n    result[\"remaining_issues\"].append(f\"{c}: {v} missing values\")\n    result[\"schema_ok\"] = False\nrem_dupes = int(df.duplicated().sum())\nif rem_dupes:\n    result[\"remaining_issues\"].append(f\"{rem_dupes} duplicate rows remain\")\n    result[\"schema_ok\"] = False\nenv[\"validation_result\"] = result",
          "output": {
            "name": "validationResult",
            "typeName": "Record",
            "fields": [
              {"name": "schema_ok", "typeName": "Boolean"},
              {"name": "remaining_issues", "typeName": "List<String>"},
              {"name": "row_count", "typeName": "Integer"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "computeStats",
          "capability": "execute_python",
          "description": "Compute quarterly statistics from repaired data.",
          "code": "import pandas as pd\nrepair = ${repairSummary}\ndf = pd.read_json(repair[\"repaired_data\"])\nstats = {\"quarter\": \"\", \"total_revenue\": 0.0, \"total_units\": 0, \"avg_order_value\": 0.0, \"num_transactions\": len(df), \"product_count\": 0}\nfor k, v in {\"q1\": \"Q1\", \"q2\": \"Q2\", \"q3\": \"Q3\", \"q4\": \"Q4\"}.items():\n    if k in \"${item}\".lower():\n        stats[\"quarter\"] = v\n        break\nrev_cols = [c for c in df.columns if any(w in c.lower() for w in [\"revenue\", \"amount\", \"total\"])]\nif rev_cols:\n    stats[\"total_revenue\"] = float(df[rev_cols[0]].sum())\nunit_cols = [c for c in df.columns if any(w in c.lower() for w in [\"unit\", \"quantity\", \"qty\"])]\nif unit_cols:\n    stats[\"total_units\"] = int(df[unit_cols[0]].sum())\n    if stats[\"total_units\"] > 0 and rev_cols:\n        stats[\"avg_order_value\"] = stats[\"total_revenue\"] / stats[\"total_units\"]\nprod_cols = [c for c in df.columns if any(w in c.lower() for w in [\"product\", \"item\", \"sku\"])]\nif prod_cols:\n    stats[\"product_count\"] = int(df[prod_cols[0]].nunique())\nenv[\"quarter_stats\"] = stats",
          "output": {
            "name": "quarterStats",
            "typeName": "Record",
            "fields": [
              {"name": "quarter", "typeName": "String"},
              {"name": "total_revenue", "typeName": "Number"},
              {"name": "total_units", "typeName": "Integer"},
              {"name": "avg_order_value", "typeName": "Number"},
              {"name": "num_transactions", "typeName": "Integer"},
              {"name": "product_count", "typeName": "Integer"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "combineResults",
          "capability": "execute_python",
          "description": "Combine all per-file results into a single record for collection.",
          "code": "env[\"file_result\"] = {\"schema\": ${schema}, \"detectedIssues\": ${detectedIssues}, \"repairSummary\": ${repairSummary}, \"validationResult\": ${validationResult}, \"quarterStats\": ${quarterStats}}",
          "output": {
            "name": "fileResult",
            "typeName": "Record",
            "fields": [
              {"name": "schema", "typeName": "Record"},
              {"name": "detectedIssues", "typeName": "Record"},
              {"name": "repairSummary", "typeName": "Record"},
              {"name": "validationResult", "typeName": "Record"},
              {"name": "quarterStats", "typeName": "Record"}
            ]
          }
        }
      ]
    },
    {
      "kind": "primitive",
      "name": "mergeResults",
      "capability": "execute_python",
      "description": "Merge all per-file results into a unified dataset for cross-quarter analysis.",
      "code": "results = ${fileResults}\nmerged = {\"files_analyzed\": len(results), \"quarters\": [], \"all_issues\": [], \"all_repairs\": [], \"all_validations\": [], \"total_revenue\": 0.0, \"total_units\": 0, \"total_transactions\": 0}\nfor r in results:\n    if \"quarterStats\" in r:\n        merged[\"quarters\"].append(r[\"quarterStats\"])\n        merged[\"total_revenue\"] += r[\"quarterStats\"].get(\"total_revenue\", 0)\n        merged[\"total_units\"] += r[\"quarterStats\"].get(\"total_units\", 0)\n        merged[\"total_transactions\"] += r[\"quarterStats\"].get(\"num_transactions\", 0)\n    if \"detectedIssues\" in r:\n        merged[\"all_issues\"].append(r[\"detectedIssues\"])\n    if \"repairSummary\" in r:\n        merged[\"all_repairs\"].append(r[\"repairSummary\"])\n    if \"validationResult\" in r:\n        merged[\"all_validations\"].append(r[\"validationResult\"])\nenv[\"merged_results\"] = merged",
      "output": {
        "name": "mergedResults",
        "typeName": "Record",
        "fields": [
          {"name": "files_analyzed", "typeName": "Integer"},
          {"name": "quarters", "typeName": "List<Record>"},
          {"name": "all_issues", "typeName": "List<Record>"},
          {"name": "all_repairs", "typeName": "List<Record>"},
          {"name": "all_validations", "typeName": "List<Record>"},
          {"name": "total_revenue", "typeName": "Number"},
          {"name": "total_units", "typeName": "Integer"},
          {"name": "total_transactions", "typeName": "Integer"}
        ]
      }
    },
    {
      "kind": "primitive",
      "name": "qualityReview",
      "capability": "execute_python",
      "description": "Evaluate overall data quality, assign a grade, and produce recommendations.",
      "code": "merged = ${mergedResults}\nreview = {\"overall_grade\": \"A\", \"critical_findings\": [], \"recommendations\": [], \"files_passed\": 0, \"files_with_issues\": 0}\nfor v in merged.get(\"all_validations\", []):\n    if v.get(\"schema_ok\", True):\n        review[\"files_passed\"] += 1\n    else:\n        review[\"files_with_issues\"] += 1\n        review[\"critical_findings\"].extend(v.get(\"remaining_issues\", []))\nfor issue_list in merged.get(\"all_issues\", []):\n    if issue_list.get(\"duplicates\", 0) > 10:\n        review[\"critical_findings\"].append(f\"High duplicate count: {issue_list['duplicates']}\")\n    for col, cnt in issue_list.get(\"missing\", {}).items():\n        if cnt > 100:\n            review[\"critical_findings\"].append(f\"High missing values in {col}: {cnt}\")\nif review[\"files_with_issues\"] > 2:\n    review[\"overall_grade\"] = \"C\"\nelif review[\"files_with_issues\"] > 0:\n    review[\"overall_grade\"] = \"B\"\nif review[\"critical_findings\"]:\n    review[\"recommendations\"].append(\"Implement stricter data validation at ingestion\")\n    review[\"recommendations\"].append(\"Add automated data quality monitoring\")\nenv[\"quality_review\"] = review",
      "output": {
        "name": "qualityReview",
        "typeName": "Record",
        "fields": [
          {"name": "overall_grade", "typeName": "String"},
          {"name": "critical_findings", "typeName": "List<String>"},
          {"name": "recommendations", "typeName": "List<String>"},
          {"name": "files_passed", "typeName": "Integer"},
          {"name": "files_with_issues", "typeName": "Integer"}
        ]
      }
    },
    {
      "kind": "primitive",
      "name": "generateReport",
      "capability": "execute_python",
      "description": "Generate a consolidated Markdown report with an evidence log.",
      "code": "import datetime\nmerged = ${mergedResults}\nreview = ${qualityReview}\nnow = datetime.datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\")\nmd = \"\"\nmd += \"# Quarterly Sales Data Quality Report\\n\\n\"\nmd += f\"**Generated:** {now}\\n\\n\"\nmd += \"## Executive Summary\\n\\n\"\nmd += f\"- **Files Analyzed:** {merged['files_analyzed']}\\n\"\nmd += f\"- **Overall Quality Grade:** {review['overall_grade']}\\n\"\nmd += f\"- **Total Revenue:** ${merged['total_revenue']:,.2f}\\n\"\nmd += f\"- **Total Units Sold:** {merged['total_units']:,}\\n\"\nmd += f\"- **Total Transactions:** {merged['total_transactions']:,}\\n\\n\"\nmd += \"## Quarterly Breakdown\\n\\n\"\nfor q in merged[\"quarters\"]:\n    md += f\"### {q.get('quarter', 'Unknown')}\\n\\n\"\n    md += f\"- Revenue: ${q.get('total_revenue', 0):,.2f}\\n\"\n    md += f\"- Units: {q.get('total_units', 0):,}\\n\"\n    md += f\"- Transactions: {q.get('num_transactions', 0):,}\\n\"\n    md += f\"- Avg Order Value: ${q.get('avg_order_value', 0):,.2f}\\n\\n\"\nmd += \"## Data Quality Issues Detected\\n\\n\"\nfor i, issue in enumerate(merged[\"all_issues\"]):\n    md += f\"### File {i+1}\\n\\n\"\n    if issue.get(\"type_errors\"):\n        md += f\"- **Type Errors:** {issue['type_errors']}\\n\"\n    if issue.get(\"duplicates\"):\n        md += f\"- **Duplicates:** {issue['duplicates']} rows\\n\"\n    md += \"\\n\"\nmd += \"## Repairs Applied\\n\\n\"\nfor i, repair in enumerate(merged[\"all_repairs\"]):\n    md += f\"### File {i+1}\\n\\n\"\n    md += f\"- Rows Dropped: {repair.get('rows_dropped', 0)}\\n\"\n    md += f\"- Values Imputed: {repair.get('values_imputed', 0)}\\n\"\n    for action in repair.get(\"actions\", []):\n        md += f\"  - {action}\\n\"\n    md += \"\\n\"\nmd += \"## Validation Results\\n\\n\"\nfor i, v in enumerate(merged[\"all_validations\"]):\n    status = \"PASS\" if v.get(\"schema_ok\") else \"FAIL\"\n    md += f\"- **File {i+1}:** {status} (rows: {v.get('row_count', 0)})\\n\"\n    for issue in v.get(\"remaining_issues\", []):\n        md += f\"  - {issue}\\n\"\nmd += \"\\n## Quality Review\\n\\n\"\nmd += f\"- **Grade:** {review['overall_grade']}\\n\"\nmd += f\"- **Files Passed:** {review['files_passed']}\\n\"\nmd += f\"- **Files with Issues:** {review['files_with_issues']}\\n\"\nif review[\"critical_findings\"]:\n    md += \"\\n### Critical Findings\\n\\n\"\n    for f in review[\"critical_findings\"]:\n        md += f\"- {f}\\n\"\nif review[\"recommendations\"]:\n    md += \"\\n### Recommendations\\n\\n\"\n    for r in review[\"recommendations\"]:\n        md += f\"- {r}\\n\"\nmd += \"\\n## Evidence Log\\n\\n\"\nmd += \"| Step | Description |\\n\"\nmd += \"|------|-------------|\\n\"\nmd += \"| Schema Inspection | Inspected CSV schema for each file |\\n\"\nmd += \"| Issue Detection | Ran type, missing, duplicate, and outlier checks |\\n\"\nmd += \"| Repair | Dropped duplicates, imputed missing values, coerced types |\\n\"\nmd += \"| Revalidation | Verified repairs resolved all detectable issues |\\n\"\nmd += \"| Statistics | Computed quarterly revenue, units, and transaction counts |\\n\"\nmd += \"| Merge | Combined all per-file results into a unified dataset |\\n\"\nmd += \"| Review | Evaluated overall data quality and flagged critical findings |\\n\"\nenv[\"report_markdown\"] = md",
      "output": {
        "name": "report",
        "typeName": "String",
        "fields": []
      }
    }
  ],
  "dataFlow": [
